using UnityEngine;
using UnityEngine.UI;
using ZFrame.Core;

namespace ZFrame.View
{
    /// <summary>
    /// Sample panel view (TASK-A-M3-01, committed for framework acceptance):
    /// a full-screen blocking Popup with one status text and one button. The
    /// button FIRES an EventBus event (<see cref="UiTestButtonClickedEvent"/>);
    /// its presenter (<see cref="TestPanelPresenter"/>) subscribes and pushes
    /// text updates back into <see cref="SetStatus"/> — the full MVP loop over
    /// the EventBus. Prefab is code-generated by <c>ZFrame.View.UISetup</c>
    /// at <c>Assets/UI/Resources/UI_TestPanel.prefab</c> (resource key
    /// "ui_test_panel" — see <see cref="DefaultConfig"/>; note Resources keys
    /// are case-sensitive on Android, the generated file name mirrors the key's
    /// letters and the Addressables migration will make this explicit).
    /// </summary>
    public sealed class TestPanelView : UIViewBase
    {
        /// <summary>Default config: blocking Popup with a fade-in, no instance cache.</summary>
        public static PanelConfig DefaultConfig { get; } = PanelConfig.Create(
            prefabKey: "ui_test_panel",
            layer: UIConsts.UILayer.Popup,
            blockMask: true,
            animIn: PanelAnim.Fade);

        [SerializeField] private Text _statusText;
        [SerializeField] private Button _testButton;

        private int _clickCount;

        /// <summary>Status text of the panel (driven by the presenter; tests assert on it).</summary>
        public string StatusText => _statusText != null ? _statusText.text : null;

        /// <summary>Exposed so the presenter-free setup can also validate wiring without clicking through the EventBus.</summary>
        public Button TestButton => _testButton;

        public override void OnInit(object args)
        {
            _clickCount = 0;
            if (_testButton != null)
            {
                _testButton.onClick.AddListener(OnButtonClicked);
            }
        }

        protected override void OnViewDestroy()
        {
            if (_testButton != null)
            {
                _testButton.onClick.RemoveListener(OnButtonClicked);
            }
        }

        /// <summary>Presenter-driven status update.</summary>
        public void SetStatus(string status)
        {
            if (_statusText != null)
            {
                _statusText.text = status;
            }
        }

        private void OnButtonClicked()
        {
            _clickCount++;
            EventBus.Fire(new UiTestButtonClickedEvent { ClickCount = _clickCount });
        }
    }
}
